3	function pyStrRepr(s) {
4	  // CPython quote selection: single quotes by default; if the string
5	  // contains a single quote but no double quote, use double quotes.
6	  const hasSingle = s.includes("'");
7	  const hasDouble = s.includes('"');
8	  const quote = hasSingle && !hasDouble ? '"' : "'";
9	  let out = quote;
10	  for (const ch of s) {
11	    const code = ch.codePointAt(0);
12	    if (ch === '\\') {
13	      out += '\\\\';
14	    } else if (ch === quote) {
15	      out += '\\' + quote;
16	    } else if (ch === '\n') {
17	      out += '\\n';
18	    } else if (ch === '\r') {
19	      out += '\\r';
20	    } else if (ch === '\t') {
21	      out += '\\t';
22	    } else if (code < 0x20 || code === 0x7f) {
23	      out += '\\x' + code.toString(16).padStart(2, '0');
24	    } else {
25	      out += ch;
26	    }
27	  }
28	  return out + quote;
29	}
