24	      }
25	    }
26	    for (const k of keys2) {
27	      if (!(k in t1)) {
28	        added.push(pathFor(k));
29	      } else if (t1[k] !== t2[k]) {
30	        changedNew[pathFor(k)] = t2[k];
31	      }
32	    }
33	
